import json,hashlib,os,struct
from Crypto.Cipher import AES,ChaCha20
ent=json.load(open('store/jobs/j000107/out/entries.json'))['entries']; pw=next(e['Password'] for e in ent if 'Recycle Bin' in e.get('_groups',[])).encode()
files=['store/jobs/j000130/out/archive/contact/instance1/config.dbx','store/jobs/j000130/out/archive/contact/instance1/contacts_polaris.db','store/jobs/j000130/out/archive/contact/instance_db/instance.dbx']
known=b'SQLite format 3\0'
kdfs={'md5':hashlib.md5(pw).digest(),'sha1':hashlib.sha1(pw).digest(),'sha256':hashlib.sha256(pw).digest(),'sha512a':hashlib.sha512(pw).digest()[:32],'sha512b':hashlib.sha512(pw).digest()[32:],'raw16':pw[:16],'rawlast16':pw[-16:]}
res=[]; scores=[]
for fp in files:
 b=open(fp,'rb').read(); page=b[:4096];
 for kn,k in kdfs.items():
  # AES ECB known first block
  if len(k) in (16,24,32):
   for op in ('decrypt','encrypt'):
    got=getattr(AES.new(k,AES.MODE_ECB),op)(page[:16]);
    if got==known:res.append([fp,kn,'aes-ecb',op])
  # CTR variants last 8/12/16 nonce-ish
  if len(k) in (16,24,32):
   for nl in (8,12):
    nonce=page[4096-12:4096-12+nl] if nl<=12 else page[-nl:]
    for initial in (0,1):
     try:got=AES.new(k,AES.MODE_CTR,nonce=nonce,initial_value=initial).decrypt(page[:16])
     except:continue
     eq=sum(a==b for a,b in zip(got,known)); scores.append([eq,fp,kn,f'aes-ctr-n{nl}-i{initial}',got.hex()])
     if got==known:res.append([fp,kn,f'aes-ctr-n{nl}-i{initial}'])
  if len(k)==32:
   for nl in (8,12):
    nonce=page[-nl:]
    try:got=ChaCha20.new(key=k,nonce=nonce).decrypt(page[:16])
    except:continue
    eq=sum(a==b for a,b in zip(got,known)); scores.append([eq,fp,kn,f'chacha-n{nl}',got.hex()])
    if got==known:res.append([fp,kn,f'chacha-n{nl}'])
print('matches',res);print('best',sorted(scores,reverse=True)[:10])
open(os.environ['OUT']+'/page-cipher-tests.json','w').write(json.dumps({'matches':res,'best_scores':sorted(scores,reverse=True)[:25],'kdfs':list(kdfs)},indent=2))
